(2,'workflow_4_fca4e8aa',4,'{\"error\": null, \"profile\": {\"goal\": \"系统学习计算机视觉，为之后找工作做准备\", \"grade\": \"大三\", \"major\": \"人工智能\", \"weakness\": [], \"interests\": [\"计算机视觉\", \"机器学习\", \"人工智能\"], \"coding_ability\": \"中级\", \"learning_style\": \"\", \"knowledge_level\": \"有Python基础、学过机器学习\"}, \"user_id\": 4, \"progress\": 0.9230769230769232, \"evaluated\": false, \"ppt_video\": {\"oss_key\": \"videos/4/1/teaching_video.mp4\", \"video_url\": \"https://video-xn-oss.oss-cn-beijing.aliyuncs.com/videos/4/1/teaching_video.mp4?v=88C2BBA2A9CB3EEBA5F4EBEE9D66A29D\", \"pages_count\": 8, \"duration_seconds\": 91.9}, \"evaluation\": null, \"session_id\": \"workflow_4_fca4e8aa\", \"current_step\": \"quality_evaluate\", \"learning_path\": {\"stages\": [{\"title\": \"计算机视觉基础与数学强化\", \"stage_id\": 1, \"description\": \"建立扎实的数学基础，重点掌握矩阵运算、特征值分解、多元高斯分布等核心概念。配合Python实现数值计算实验，推荐《统计学习方法》第4章及CS231n笔记。\", \"estimated_hours\": 25, \"knowledge_points\": [\"线性代数基础\", \"概率统计与贝叶斯定理\", \"最优化方法(梯度下降)\", \"Python科学计算库(NumPy/Pandas)\"], \"recommended_resource_types\": [\"书籍\", \"在线课程\", \"文档\"]}, {\"title\": \"经典机器学习框架构建\", \"stage_id\": 2, \"description\": \"通过ImageNet子集进行端到端训练实验，理解数据预处理流程。重点掌握sklearn接口调用与超参数调优技巧，完成至少两个不同架构的对比实验报告。\", \"estimated_hours\": 30, \"knowledge_points\": [\"监督学习全流程(SVM/决策树)\", \"特征工程方法论\", \"模型评估指标(AUC/F1)\", \"交叉验证策略\"], \"recommended_resource_types\": [\"视频课程\", \"开源数据集\", \"Kaggle竞赛\"]}, {\"title\": \"深度学习核心突破\", \"stage_id\": 3, \"description\": \"复现经典网络结构并分析各层作用机制，使用TensorFlow/PyTorch实现自定义卷积核可视化。重点关注注意力机制与轻量化网络的设计思想。\", \"estimated_hours\": 40, \"knowledge_points\": [\"CNN架构演进(LeNet→ResNet)\", \"损失函数设计(Softmax/Focal Loss)\", \"正则化技术(Dropout/BatchNorm)\", \"GPU并行计算原理\"], \"recommended_resource_types\": [\"学术论文精读\", \"GitHub源码解析\", \"顶会Workshop录像\"]}, {\"title\": \"计算机视觉专项攻坚\", \"stage_id\": 4, \"description\": \"基于COCO数据集完成多尺度检测任务，尝试FPN特征融合方案。探索TensorRT部署优化方案，对比CPU/GPU推理速度差异，撰写性能分析报告。\", \"estimated_hours\": 50, \"knowledge_points\": [\"目标检测(YOLO系列)\", \"语义分割(U-Net变体)\", \"三维重建基础\", \"实时推理加速技术\"], \"recommended_resource_types\": [\"工业案例研究\", \"自动驾驶仿真平台\", \"模型压缩指南\"]}, {\"title\": \"毕业设计与求职冲刺\", \"stage_id\": 5, \"description\": \"独立完成具有创新性的CV课题（如弱监督学习），整理成可展示的作品集。针对性练习行为面高频考题，熟悉各大厂笔试题型特点。\", \"estimated_hours\": 35, \"knowledge_points\": [\"完整项目开发流程\", \"技术博客撰写规范\", \"模拟面试题库\", \"行业前沿动态追踪\"], \"recommended_resource_types\": [\"导师指导\", \"校友分享会\", \"内推渠道\"]}]}, \"profile_built\": true, \"steps_history\": [{\"step\": \"build_profile\", \"status\": \"skipped\", \"timestamp\": \"2026-07-19T12:44:49.107981\"}, {\"step\": \"generate_path\", \"status\": \"completed\", \"timestamp\": \"2026-07-19T12:44:49.126130\"}, {\"step\": \"generate_knowledge_graph\", \"status\": \"completed\", \"timestamp\": \"2026-07-19T12:45:00.849290\"}, {\"step\": \"generate_document\", \"status\": \"completed\", \"timestamp\": \"2026-07-19T12:45:52.962889\"}, {\"step\": \"generate_ppt_video\", \"status\": \"completed\", \"timestamp\": \"2026-07-19T12:46:41.950146\"}, {\"step\": \"generate_mindmap\", \"status\": \"completed\", \"timestamp\": \"2026-07-19T12:47:44.074478\"}, {\"step\": \"generate_questions\", \"status\": \"completed\", \"timestamp\": \"2026-07-19T12:47:50.365304\"}, {\"step\": \"generate_code\", \"status\": \"completed\", \"timestamp\": \"2026-07-19T12:48:07.841436\"}, {\"step\": \"generate_reading\", \"status\": \"completed\", \"timestamp\": \"2026-07-19T12:48:25.562614\"}, {\"step\": \"generate_glossary\", \"status\": \"completed\", \"timestamp\": \"2026-07-19T12:48:41.554436\"}, {\"step\": \"generate_knowledge_link\", \"status\": \"completed\", \"timestamp\": \"2026-07-19T12:48:52.936159\"}, {\"step\": \"generate_summary\", \"status\": \"completed\", \"timestamp\": \"2026-07-19T12:49:14.459636\"}, {\"step\": \"quality_evaluate\", \"status\": \"completed\", \"timestamp\": \"2026-07-19T12:49:30.452984\"}], \"code_generated\": true, \"path_generated\": true, \"mindmap_generated\": true, \"reading_generated\": true, \"summary_generated\":